package com.jarvis.watchbridge.ui

import android.graphics.BitmapFactory
import android.util.Base64
import androidx.compose.animation.core.RepeatMode
import androidx.compose.animation.core.animateFloat
import androidx.compose.animation.core.infiniteRepeatable
import androidx.compose.animation.core.rememberInfiniteTransition
import androidx.compose.animation.core.tween
import androidx.compose.foundation.Image
import androidx.compose.foundation.background
import androidx.compose.foundation.border
import androidx.compose.foundation.layout.Box
import androidx.compose.foundation.layout.fillMaxWidth
import androidx.compose.foundation.layout.height
import androidx.compose.foundation.shape.RoundedCornerShape
import androidx.compose.runtime.Composable
import androidx.compose.runtime.getValue
import androidx.compose.runtime.remember
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.draw.clip
import androidx.compose.ui.draw.scale
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.asImageBitmap
import androidx.compose.ui.layout.ContentScale
import androidx.compose.ui.unit.dp

private const val JARVIS_PORTRAIT_BASE64 = ""

@Composable
fun JarvisPortrait(state: JarvisVisualState, modifier: Modifier = Modifier) {
    val bytes = remember { Base64.decode(JARVIS_PORTRAIT_BASE64, Base64.DEFAULT) }
    val bitmap = remember { BitmapFactory.decodeByteArray(bytes, 0, bytes.size).asImageBitmap() }
    val transition = rememberInfiniteTransition(label = "portrait-pulse")
    val pulse by transition.animateFloat(
        initialValue = 0.985f,
        targetValue = 1.015f,
        animationSpec = infiniteRepeatable(tween(if (state == JarvisVisualState.SPEAKING) 320 else 1200), RepeatMode.Reverse),
        label = "portrait-scale"
    )
    val border = when (state) {
        JarvisVisualState.ALERT -> Color(0xFFFF4B4B)
        JarvisVisualState.LISTENING -> Color(0xFF8DDCFF)
        JarvisVisualState.THINKING -> Color(0xFF4F9DFF)
        JarvisVisualState.SPEAKING -> Color(0xFF59C9FF)
        JarvisVisualState.IDLE -> Color(0xFF173A57)
    }
    Box(
        modifier
            .fillMaxWidth()
            .height(360.dp)
            .scale(pulse)
            .clip(RoundedCornerShape(28.dp))
            .border(2.dp, border, RoundedCornerShape(28.dp))
            .background(Color(0xFF08111A)),
        contentAlignment = Alignment.Center
    ) {
        Image(
            bitmap = bitmap,
            contentDescription = "JARVIS AI portrait",
            modifier = Modifier.fillMaxWidth().height(360.dp),
            contentScale = ContentScale.Crop
        )
    }
}
